-- CREAR TABLA PRODUCTO_PROVEEDOR
CREATE TABLE IF NOT EXISTS "PRODUCTO_PROVEEDOR" (
    id SERIAL PRIMARY KEY,
    product_barcode VARCHAR(50) NOT NULL,
    provider_rut VARCHAR(20) NOT NULL,
    is_primary BOOLEAN DEFAULT FALSE,
    has_exchange BOOLEAN,
    withdrawal_days INTEGER,
    exchange_policy TEXT,
    mundo VARCHAR(50),
    marca VARCHAR(50),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(product_barcode, provider_rut)
);

CREATE INDEX idx_pp_producto ON "PRODUCTO_PROVEEDOR"(product_barcode);
CREATE INDEX idx_pp_proveedor ON "PRODUCTO_PROVEEDOR"(provider_rut);
CREATE INDEX idx_pp_principal ON "PRODUCTO_PROVEEDOR"(product_barcode) WHERE is_primary = TRUE;

